//! cbae_batchd — Batch processing daemon crate.
//!
//! Exposes a C-compatible FFI surface called by the C engine via
//! include/rust/cbae_batchd.h (generated by cbindgen).
//!
//! ARCHITECTURE:
//!   JobQueue   — crossbeam channel wrapping a persistent SQLite queue
//!   WorkerPool — fixed Rayon thread pool, one thread per CPU core
//!   Scheduler  — priority-based job dispatch from queue to workers
//!
//! WHY RUST:
//!   The C equivalent (src/batch/*.c) would manage shared mutable state
//!   (the job queue) across multiple threads using raw mutexes and
//!   condition variables.  A single missed lock acquisition or a
//!   use-after-free on a freed job struct running as root = privilege
//!   escalation.  Rust's type system prevents both classes of bug at
//!   compile time.

pub mod job;
pub mod queue;
pub mod worker;
pub mod scheduler;
pub mod ffi;

pub use job::{Job, JobId, JobStage};
pub use queue::JobQueue;
pub use scheduler::Scheduler;
